import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.Ce1WstT_.js";const u=JSON.parse('{"title":"2. Problem Statement","description":"","frontmatter":{},"headers":[],"relativePath":"overview/problem-statement.md","filePath":"overview/problem-statement.md"}'),i={name:"overview/problem-statement.md"};function s(l,e,r,c,m,d){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_2-problem-statement" tabindex="-1">2. Problem Statement <a class="header-anchor" href="#_2-problem-statement" aria-label="Permalink to &quot;2. Problem Statement&quot;">​</a></h1><p>Small-to-medium wholesale and distribution businesses often struggle with fragmented operational processes. The Mini ERP + CRM Operations Portal was built to solve specific organizational issues:</p><h3 id="customer-information-management" tabindex="-1">Customer Information Management <a class="header-anchor" href="#customer-information-management" aria-label="Permalink to &quot;Customer Information Management&quot;">​</a></h3><p>Sales teams lack a centralized directory for leads and active customers. Information is often siloed, making it difficult to hand over accounts or track historical context.</p><h3 id="follow-up-management" tabindex="-1">Follow-up Management <a class="header-anchor" href="#follow-up-management" aria-label="Permalink to &quot;Follow-up Management&quot;">​</a></h3><p>Without a structured system, sales representatives lose track of when to contact prospects, resulting in dropped leads and lost revenue.</p><h3 id="product-catalog-management" tabindex="-1">Product Catalog Management <a class="header-anchor" href="#product-catalog-management" aria-label="Permalink to &quot;Product Catalog Management&quot;">​</a></h3><p>Maintaining a master product list across different departments often leads to pricing discrepancies and SKU mismatches.</p><h3 id="inventory-visibility" tabindex="-1">Inventory Visibility <a class="header-anchor" href="#inventory-visibility" aria-label="Permalink to &quot;Inventory Visibility&quot;">​</a></h3><p>Warehouse and sales teams lack real-time visibility into available stock, often resulting in sales representatives promising inventory that does not exist.</p><h3 id="stock-movement-tracking" tabindex="-1">Stock Movement Tracking <a class="header-anchor" href="#stock-movement-tracking" aria-label="Permalink to &quot;Stock Movement Tracking&quot;">​</a></h3><p>Modifying stock without an immutable ledger creates accountability issues. It becomes impossible to audit whether stock was lost, damaged, sold, or manually adjusted.</p><h3 id="sales-challan-management" tabindex="-1">Sales Challan Management <a class="header-anchor" href="#sales-challan-management" aria-label="Permalink to &quot;Sales Challan Management&quot;">​</a></h3><p>Fulfillment involves creating dispatch documents (Challans). Without digital transaction locks, multiple salespeople might simultaneously confirm challans for the same low-stock item, creating negative inventory balances.</p><h3 id="role-based-access" tabindex="-1">Role-Based Access <a class="header-anchor" href="#role-based-access" aria-label="Permalink to &quot;Role-Based Access&quot;">​</a></h3><p>Accounts should not modify inventory, and sales should not create product catalogs. Lacking Role-Based Access Control (RBAC) causes internal data corruption.</p><h3 id="operational-visibility" tabindex="-1">Operational Visibility <a class="header-anchor" href="#operational-visibility" aria-label="Permalink to &quot;Operational Visibility&quot;">​</a></h3><p>Executives require a high-level summary of active leads, low stock, and daily shipments to make informed business decisions.</p>',18)])])}const p=a(i,[["render",s]]);export{u as __pageData,p as default};
